"""Stage cover images in 10,000-image ZIP batches and verify archive.org uploads."""

import datetime
import fcntl
from itertools import groupby
import os
import re
import time
import zipfile
from contextlib import contextmanager
from subprocess import run

from openlibrary.coverstore import config, db

SIZES = ("", "s", "m", "l")


def _size(size):
    size = size.lower()
    if size not in SIZES:
        raise ValueError("invalid cover size")
    return size


class Cover:
    def __init__(self, attributes):
        self.__dict__.update(attributes)

    def local_path(self, size=""):
        filename = getattr(self, "filename_" + size if size else "filename", None)
        if (
            not config.data_root
            or not filename
            or filename.startswith(("http://", "https://"))
        ):
            return None
        root = os.path.abspath(os.path.join(config.data_root, "localdisk"))
        path = os.path.abspath(os.path.join(root, filename))
        return path if os.path.commonpath((root, path)) == root else None

    def delete_file(self, size=""):
        path = self.local_path(size)
        if path and os.path.isfile(path):
            os.remove(path)

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        number = int(cover_id)
        if not 0 <= number < 10_000_000_000:
            raise ValueError("cover ID must fit in ten digits")
        padded = f"{number:010d}"
        return padded[:4], padded[4:6]

    @staticmethod
    def get_cover_url(cover_id, size="", ext="jpg", protocol="https"):
        size = _size(size)
        if protocol not in ("http", "https"):
            raise ValueError("invalid protocol")
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        prefix = f"{size}_" if size else ""
        item = f"{prefix}covers_{item_id}"
        archive_name = f"{item}_{batch_id}.zip"
        filename = f'{int(cover_id):010d}{f"-{size.upper()}" if size else ""}.{ext}'
        return f"{protocol}://archive.org/download/{item}/{archive_name}/{filename}"


class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id = item_id
        self.batch_id = batch_id
        self.size = _size(size) if size is not None else None

    def _norm_ids(self):
        return f"{int(self.item_id):04d}", f"{int(self.batch_id):02d}"

    @classmethod
    def get_relpath(cls, item_id, batch_id, size="", ext="zip"):
        size = _size(size)
        item_id, batch_id = cls(item_id, batch_id)._norm_ids()
        prefix = f"{size}_" if size else ""
        item = f"{prefix}covers_{item_id}"
        return os.path.join("items", item, f"{item}_{batch_id}.{ext}")

    @classmethod
    def get_abspath(cls, item_id, batch_id, size="", ext="zip"):
        return os.path.join(
            config.data_root, cls.get_relpath(item_id, batch_id, size, ext)
        )

    def process_pending(self, upload=False, finalize=False, test=True, uploader=None):
        uploader = uploader or Uploader()
        sizes = SIZES if self.size is None else (self.size,)
        with batch_lock(self.item_id, self.batch_id):
            pending = []
            for size in sizes:
                path = self.get_abspath(self.item_id, self.batch_id, size)
                if os.path.isfile(path):
                    item = os.path.basename(os.path.dirname(path))
                    pending.append((size, path, item))
            if finalize and pending:
                start = int(self.item_id) * 1_000_000 + int(self.batch_id) * 10_000
                end = CoverDB._get_batch_end_id(start)
                waiting = db.getdb().select(
                    "cover",
                    where="id >= $start AND id <= $end AND archived = $no AND failed = $no",
                    vars={"start": start, "end": end, "no": False},
                    limit=1,
                )
                if list(waiting):
                    raise RuntimeError("batch contains unarchived covers")
            for size, path, item in pending:
                if (
                    upload
                    and not test
                    and not uploader.is_uploaded(item, os.path.basename(path))
                ):
                    uploader.upload(item, [path])
                if finalize and not uploader.is_uploaded(item, os.path.basename(path)):
                    raise RuntimeError(f"upload not verified: {path}")
            if finalize and not test:
                for size, path, _item in pending:
                    CoverDB().update_completed_batch(
                        self.item_id, self.batch_id, size=size
                    )
                    os.remove(path)

    def finalize(self, start_id=None, test=True):
        self.process_pending(finalize=True, test=test)


@contextmanager
def batch_lock(item_id, batch_id):
    """Serialize writers and finalizers for a batch on this coverserver."""
    path = Batch.get_abspath(item_id, batch_id, ext="lock")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "a+b") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


class ZipManager:
    def __init__(self):
        self.zipfiles = {}

    def add_file(self, name, filepath, mtime):
        match = re.fullmatch(r"(\d{10})(?:-([SML]))?\.([A-Za-z0-9]+)", name)
        if not match:
            raise ValueError(f"invalid cover filename: {name}")
        item_id, batch_id = Cover.id_to_item_and_batch_id(match[1])
        size = (match[2] or "").lower()
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            zf = zipfile.ZipFile(
                path, "a", compression=zipfile.ZIP_STORED, allowZip64=True
            )
            self.zipfiles[path] = (zf, set(zf.namelist()))
        zf, names = self.zipfiles[path]
        if name not in names:
            info = zipfile.ZipInfo(name, time.localtime(max(mtime, 315532800))[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, "rb") as source, zf.open(info, "w") as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            names.add(name)
        return os.path.basename(path)

    def close(self):
        for zf, _names in self.zipfiles.values():
            zf.close()
        self.zipfiles.clear()


